//! The routes the downloads work added to the Python server that this crate's server replaced (in
//! train 20, after this crate's server was written), so that `tests/pages/download-probe.html`
//! can be served by `scripts/serve-tests.sh`:
//!
//! - `/download/<name>` (GET or POST) answers generated bytes (byte `i` is `i % 251`) with a
//!   strong `ETag`, a `Last-Modified` date and `Range` support. Query parameters: `size`
//!   (bytes, default 1000), `type` (`Content-Type`, default `application/octet-stream`),
//!   `disposition` (`attachment` or `inline`; omitted by default), `filename` (for the
//!   disposition), `body=png` (a 64x64 red PNG instead of the generated bytes; `size` is then
//!   ignored), `body=text` (lines of ASCII text, `size` bytes), `rate` (bytes per second; 0,
//!   the default, is unthrottled) and `setcookie` (a `Set-Cookie` value);
//! - `POST /form-result` answers a page that follows a link to a file by itself;
//! - `--log FILE` appends one JSON line per request (see [`RequestLog`]).
//!
//! Where the Python script died with a traceback on a malformed query (a `size` that is not
//! a number) or sent a response it could not frame (a negative size, a range that ends before
//! it starts), this answers 400 or 416, and it refuses header values that contain a line
//! break (the server is loopback-only, but the page that asks is not trusted).

use std::collections::HashMap;
use std::fs::OpenOptions;
use std::io::{self, Cursor, Write};
use std::path::PathBuf;
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, UNIX_EPOCH};

use percent_encoding::{AsciiSet, NON_ALPHANUMERIC, percent_decode_str, utf8_percent_encode};

use super::files::{parse_range, saturating_number, split_url};
use super::http::{Request, Responder, reason};
use super::python::{python_int, python_strip};

/// The path prefix of the generated downloads.
pub(super) const DOWNLOAD_PREFIX: &str = "/download/";
/// The route that answers a page which follows a link to a file by itself.
pub(super) const FORM_RESULT_PATH: &str = "/form-result";

/// The bytes written per second of throttling are cut into this many pieces.
const PIECES_PER_SECOND: u64 = 10;
/// The most bytes written at once.
const CHUNK: u64 = 65_536;
/// The most text `body=text` generates (it is built in memory).
const MAX_TEXT_BYTES: i64 = 64 * 1024 * 1024;
/// Seconds since the epoch of the fixed `Last-Modified` date, so that a resumed download sees
/// the same validator as the first attempt (`Tue, 14 Nov 2023 22:13:20 GMT`).
const LAST_MODIFIED_SECONDS: u64 = 1_700_000_000;

/// `urllib.parse.quote(text, safe="")`: everything but letters, digits and `_.-~` encoded.
const QUOTE_SET: &AsciiSet = &NON_ALPHANUMERIC
    .remove(b'_')
    .remove(b'.')
    .remove(b'-')
    .remove(b'~');

/// The `--log FILE` of the server: one JSON line per request, appended to the file.
///
/// A line has the keys `method`, `path`, `cookie`, `referer`, `user_agent`, `range`, `sent`
/// (the bytes of the body sent, or null when the route does not count them) and `complete`
/// (whether the client read the body to the end, or null). The file is opened for each line,
/// so it can be read or removed while the server runs.
pub(super) struct RequestLog {
    path: PathBuf,
    write: Mutex<()>,
}

impl RequestLog {
    pub(super) fn new(path: PathBuf) -> RequestLog {
        RequestLog {
            path,
            write: Mutex::new(()),
        }
    }

    pub(super) fn record(&self, request: &Request, sent: Option<u64>, complete: Option<bool>) {
        let text = |name: &str| serde_json::Value::from(request.header(name)).to_string();
        let line = format!(
            "{{\"method\": {}, \"path\": {}, \"cookie\": {}, \"referer\": {}, \"user_agent\": {}, \"range\": {}, \"sent\": {}, \"complete\": {}}}\n",
            serde_json::Value::from(request.command.as_str()),
            serde_json::Value::from(request.path.as_str()),
            text("Cookie"),
            text("Referer"),
            text("User-Agent"),
            text("Range"),
            serde_json::Value::from(sent),
            serde_json::Value::from(complete),
        );
        // One writer at a time, so that two connections never interleave their lines.
        let _guard = self
            .write
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let written = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            .and_then(|mut file| file.write_all(line.as_bytes()));
        if let Err(error) = written {
            eprintln!(
                "serve-tests: cannot write the request log {}: {error}",
                self.path.display()
            );
        }
    }
}

/// Records a request in the log, if the server has one.
pub(super) fn record(
    log: Option<&RequestLog>,
    request: &Request,
    sent: Option<u64>,
    complete: Option<bool>,
) {
    if let Some(log) = log {
        log.record(request, sent, complete);
    }
}

/// The path of a request target, as `urllib.parse.urlsplit(target).path`.
pub(super) fn url_path(target: &str) -> &str {
    split_url(target).0
}

/// `urllib.parse.parse_qs(query)` with the last value of each name: blank values are dropped
/// and `+` and `%XX` decoded.
fn parse_query(query: &str) -> HashMap<String, String> {
    let decode = |text: &str| {
        percent_decode_str(&text.replace('+', " "))
            .decode_utf8_lossy()
            .into_owned()
    };
    let mut values = HashMap::new();
    for pair in query.split('&') {
        if let Some((name, value)) = pair.split_once('=')
            && !value.is_empty()
        {
            values.insert(decode(name), decode(value));
        }
    }
    values
}

/// A 64x64 red PNG, the same bytes every time.
fn red_png() -> &'static [u8] {
    static PNG: OnceLock<Vec<u8>> = OnceLock::new();
    PNG.get_or_init(|| {
        let picture = image::RgbImage::from_pixel(64, 64, image::Rgb([255, 0, 0]));
        let mut bytes = Cursor::new(Vec::new());
        picture
            .write_to(&mut bytes, image::ImageFormat::Png)
            .expect("encode a PNG in memory");
        bytes.into_inner()
    })
}

/// Lines of ASCII text (`line 0`, `line 1`, ...), cut to `size` bytes.
fn text_body(size: usize) -> Vec<u8> {
    let mut body = Vec::with_capacity(size.saturating_add(16).min(1 << 24));
    let mut number = 0u64;
    while body.len() < size {
        body.extend_from_slice(format!("line {number}\n").as_bytes());
        number += 1;
    }
    body.truncate(size);
    body
}

/// The fixed `Last-Modified` date.
fn last_modified() -> String {
    httpdate::fmt_http_date(UNIX_EPOCH + Duration::from_secs(LAST_MODIFIED_SECONDS))
}

/// Whether a header value can be sent as it is.
fn is_header_value(value: &str) -> bool {
    !value.contains(['\r', '\n'])
}

/// `GET` or `POST /download/<name>`: generated bytes, throttled when `rate` asks for it.
pub(super) fn send_download(
    responder: &mut Responder<'_>,
    request: &Request,
    log: Option<&RequestLog>,
) -> io::Result<()> {
    let query = parse_query(split_url(&request.path).1);
    let number = |name: &str, default: i64| match query.get(name) {
        None => Some(default),
        Some(value) => python_int(value).filter(|value| *value >= 0),
    };
    let content_type = query
        .get("type")
        .map_or("application/octet-stream", String::as_str);
    // The body when it is fixed (a picture or text), or None when it is generated as it is
    // sent; Err when `size` is not usable.
    let body: Result<Option<Vec<u8>>, ()> = match query.get("body").map(String::as_str) {
        Some("png") => Ok(Some(red_png().to_vec())),
        Some("text") => number("size", 1000)
            .filter(|size| *size <= MAX_TEXT_BYTES)
            .map(|size| Some(text_body(size as usize)))
            .ok_or(()),
        _ => Ok(None),
    };
    let (fixed, size) = match body {
        Ok(Some(bytes)) => {
            let size = bytes.len() as u64;
            (Some(bytes), Some(size))
        }
        Ok(None) => (None, number("size", 1000).map(|size| size as u64)),
        Err(()) => (None, None),
    };
    let rate = number("rate", 0).map(|rate| rate as u64);
    let disposition = query.get("disposition").map(|disposition| {
        match query.get("filename").filter(|name| !name.is_empty()) {
            Some(name) => format!("{disposition}; filename=\"{name}\""),
            None => disposition.clone(),
        }
    });
    let cookie = query.get("setcookie");
    let (Some(size), Some(rate)) = (size, rate) else {
        let result = responder.send_error(400, Some("Bad download parameters"), None);
        record(log, request, None, None);
        return result;
    };
    let values = [
        Some(content_type),
        disposition.as_deref(),
        cookie.map(String::as_str),
    ];
    if !values.iter().flatten().all(|value| is_header_value(value)) {
        let result = responder.send_error(400, Some("Bad header value"), None);
        record(log, request, None, None);
        return result;
    }

    let etag = format!(
        "\"{size}-{}\"",
        utf8_percent_encode(content_type, QUOTE_SET)
    );
    let last_modified = last_modified();
    let mut start = 0;
    let mut length = size;
    let mut content_range = None;
    // A range is honoured when it names its first byte and the validator (if any) is ours.
    let range = request
        .header("Range")
        .and_then(|header| parse_range(python_strip(header)))
        .filter(|(first, _)| !first.is_empty())
        .filter(|_| {
            request
                .header("If-Range")
                .is_none_or(|validator| validator == etag || validator == last_modified)
        });
    if let Some((first, last)) = range {
        let first = saturating_number(first);
        let last = (!last.is_empty()).then(|| saturating_number(last));
        let end = size
            .checked_sub(1)
            .map(|final_byte| last.map_or(final_byte, |last| last.min(final_byte)));
        match end {
            Some(end) if first < size && first <= end => {
                start = first;
                length = end - first + 1;
                content_range = Some(format!("bytes {first}-{end}/{size}"));
            }
            _ => {
                let result = responder.send_head(
                    416,
                    reason(416),
                    &[
                        ("Content-Range", format!("bytes */{size}")),
                        ("Content-Length", "0".into()),
                    ],
                );
                record(log, request, Some(0), Some(true));
                return result;
            }
        }
    }

    let status = if content_range.is_some() { 206 } else { 200 };
    let mut headers = vec![
        ("Content-Type", content_type.to_owned()),
        ("Content-Length", length.to_string()),
        ("ETag", etag),
        ("Last-Modified", last_modified),
    ];
    headers.extend(content_range.map(|value| ("Content-Range", value)));
    headers.extend(disposition.map(|value| ("Content-Disposition", value)));
    headers.extend(cookie.map(|value| ("Set-Cookie", value.clone())));
    responder.send_head(status, reason(status), &headers)?;

    let piece = if rate == 0 {
        CHUNK
    } else {
        (rate / PIECES_PER_SECOND).clamp(1, CHUNK)
    };
    let end = start + length;
    let mut position = start;
    let mut sent = 0;
    while position < end {
        let count = piece.min(end - position);
        let written = match &fixed {
            Some(bytes) => {
                responder.send_body(&bytes[position as usize..(position + count) as usize])
            }
            None => {
                let generated: Vec<u8> = (position..position + count)
                    .map(|byte| (byte % 251) as u8)
                    .collect();
                responder.send_body(&generated)
            }
        };
        if written.is_err() {
            // The client went away (a cancelled or paused download).
            record(log, request, Some(sent), Some(false));
            return Ok(());
        }
        position += count;
        sent += count;
        if rate != 0 {
            std::thread::sleep(Duration::from_secs_f64(count as f64 / rate as f64));
        }
    }
    record(log, request, Some(sent), Some(true));
    Ok(())
}

/// `POST /form-result`: the page a form's answer leads to. It follows a link to a file on
/// its own, to see what going back to it does (whether the form is sent again).
pub(super) fn send_form_result(
    responder: &mut Responder<'_>,
    request: &Request,
    log: Option<&RequestLog>,
) -> io::Result<()> {
    let body = "<!doctype html><title>Form result</title><h1>Form result</h1>\
<a id=f href='/download/after-post.zip?type=application/zip'>file</a>\
<script>setTimeout(() => document.getElementById('f').click(), 500)</script>";
    responder.send_head(
        200,
        reason(200),
        &[
            ("Content-Type", "text/html".into()),
            ("Content-Length", body.len().to_string()),
        ],
    )?;
    responder.send_body(body.as_bytes())?;
    record(log, request, Some(body.len() as u64), Some(true));
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn query_like_parse_qs() {
        let query = parse_query("size=10&type=text%2Fplain&size=20&blank=&x&y=a+b&=z");
        assert_eq!(query.get("size").map(String::as_str), Some("20"));
        assert_eq!(query.get("type").map(String::as_str), Some("text/plain"));
        assert_eq!(query.get("y").map(String::as_str), Some("a b"));
        assert_eq!(query.get("blank"), None);
        assert_eq!(query.get("x"), None);
        assert_eq!(query.get("").map(String::as_str), Some("z"));
    }

    #[test]
    fn text_is_lines_cut_to_size() {
        assert_eq!(text_body(0), b"");
        assert_eq!(text_body(10), b"line 0\nlin");
        assert_eq!(text_body(100).len(), 100);
    }

    #[test]
    fn the_validator_date_is_fixed() {
        assert_eq!(last_modified(), "Tue, 14 Nov 2023 22:13:20 GMT");
    }

    #[test]
    fn the_png_is_a_red_square() {
        let picture = image::load_from_memory_with_format(red_png(), image::ImageFormat::Png)
            .expect("a PNG")
            .to_rgb8();
        assert_eq!(picture.dimensions(), (64, 64));
        assert!(picture.pixels().all(|pixel| pixel.0 == [255, 0, 0]));
    }
}
